head.b:skin:
/* ═══════════════════════════════════════════════════════════════
   CYBERBIVASH® — SENTINEL APEX v23.0 GOD-MODE
   World #1 AI Cybersecurity Blogger Theme
   Production | E-E-A-T + Google Discover + News + Core Web Vitals
   ═══════════════════════════════════════════════════════════════ */
:root {
  --void:#06080d;--deep:#080c15;--surface:#0f1521;--card:#111827;--card2:#0d1420;--glass:rgba(15,21,33,0.75);
  --border:#1e293b;--border2:#243044;--border3:#2d3f5a;
  --accent:#00e5c3;--accent2:#0ea5e9;--accent3:#f59e0b;--accent4:#8b5cf6;--accent5:#ec4899;
  --danger:#ef4444;--success:#22c55e;--warning:#f59e0b;
  --accent-dim:rgba(0,229,195,0.10);--accent2-dim:rgba(14,165,233,0.10);
  --accent4-dim:rgba(139,92,246,0.10);--danger-dim:rgba(239,68,68,0.10);
  --text-primary:#ffffff;--text-secondary:#94a3b8;--text-muted:#475569;--text-dim:#2d3f5a;
  --glow:0 0 40px rgba(0,229,195,0.15);--glow2:0 0 40px rgba(14,165,233,0.15);
  --glow4:0 0 40px rgba(139,92,246,0.15);
  --radius:14px;--radius-sm:6px;--radius-xs:4px;
  --transition:all 0.25s cubic-bezier(0.4,0,0.2,1);
  --shadow:0 4px 24px rgba(0,0,0,0.4);--shadow-lg:0 8px 48px rgba(0,0,0,0.5);
}
*{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;}
body{font-family:'Inter',sans-serif;background:var(--void);color:var(--text-secondary);line-height:1.8;overflow-x:hidden;}
a{color:inherit;text-decoration:none;}
img{max-width:100%;height:auto;display:block;}
button{cursor:pointer;border:none;background:none;font-family:inherit;}
::selection{background:rgba(0,229,195,0.2);color:#fff;}

/* ── READING PROGRESS ─────────────────────────────── */
#reading-progress{position:fixed;top:0;left:0;height:3px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4),var(--accent5));width:0%;z-index:9999;transition:width 0.1s linear;box-shadow:0 0 10px rgba(0,229,195,0.5);}

/* ── SKIP NAV ─────────────────────────────────────── */
.skip-nav{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;}
.skip-nav:focus{position:fixed;top:0;left:0;width:auto;height:auto;padding:12px 20px;background:var(--accent);color:#000;font-weight:700;z-index:10000;}

/* ── TICKER ──────────────────────────────────────── */
.cdb-ticker{background:linear-gradient(90deg,#000 0%,#040a12 100%);border-bottom:1px solid var(--border);padding:7px 0;overflow:hidden;position:relative;z-index:200;}
.ticker-inner{display:flex;align-items:center;}
.ticker-label{background:linear-gradient(135deg,var(--accent),#00bfa3);color:#000;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:900;letter-spacing:2px;padding:5px 16px;white-space:nowrap;flex-shrink:0;text-transform:uppercase;clip-path:polygon(0 0,calc(100% - 10px) 0,100% 50%,calc(100% - 10px) 100%,0 100%);}
.ticker-track{overflow:hidden;flex:1;}
.ticker-content{display:inline-flex;gap:36px;animation:tickerScroll 50s linear infinite;white-space:nowrap;padding-left:36px;}
.ticker-content:hover{animation-play-state:paused;}
.ticker-item{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:11px;display:inline-flex;align-items:center;gap:8px;}
.ticker-badge{font-size:9px;padding:2px 7px;border-radius:3px;font-weight:900;letter-spacing:1px;text-transform:uppercase;flex-shrink:0;}
.ticker-badge.crit{background:var(--danger);color:#fff;}
.ticker-badge.warn{background:var(--accent3);color:#000;}
.ticker-badge.info{background:var(--accent2);color:#fff;}
.ticker-badge.zero{background:var(--accent4);color:#fff;}
.ticker-badge.live{background:var(--accent);color:#000;}
.ticker-item a{color:#e2e8f0;font-weight:600;transition:0.2s;}
.ticker-item a:hover{color:var(--accent);}
@keyframes tickerScroll{0%{transform:translateX(0);}100%{transform:translateX(-50%);}}

/* ── TOP NAV ──────────────────────────────────────── */
.cdb-topnav{background:rgba(6,8,13,0.95);border-bottom:1px solid var(--border);padding:0 24px;position:sticky;top:0;z-index:999;backdrop-filter:blur(20px) saturate(1.5);-webkit-backdrop-filter:blur(20px) saturate(1.5);}
.topnav-inner{max-width:1500px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;height:56px;gap:12px;}
.nav-logo{display:flex;align-items:center;gap:12px;flex-shrink:0;}
.nav-logo-icon{width:36px;height:36px;background:linear-gradient(135deg,var(--accent),#00bfa3);border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:18px;box-shadow:0 0 16px rgba(0,229,195,0.3);}
.nav-logo-text{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:16px;letter-spacing:0.5px;}
.nav-logo-text span{color:var(--accent);}
.nav-logo-sub{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;display:block;line-height:1;}
.nav-links{display:flex;align-items:center;gap:1px;flex:1;justify-content:center;}
.nav-link{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:6px 11px;border-radius:5px;transition:var(--transition);white-space:nowrap;border:1px solid transparent;}
.nav-link:hover{color:var(--accent);border-color:var(--border);background:var(--accent-dim);}
.nav-link.active{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.nav-link.highlight{color:#000;background:var(--accent);border-color:var(--accent);box-shadow:0 0 20px rgba(0,229,195,0.25);}
.nav-link.highlight:hover{background:#00ffdc;box-shadow:0 0 25px rgba(0,229,195,0.5);}
.nav-link.api-link{color:var(--accent2);border-color:rgba(14,165,233,0.15);}
.nav-link.api-link:hover{background:var(--accent2-dim);color:#fff;border-color:rgba(14,165,233,0.3);}
.nav-search-btn{display:flex;align-items:center;gap:6px;color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;padding:6px 10px;border:1px solid var(--border);border-radius:5px;background:var(--surface);cursor:pointer;transition:var(--transition);white-space:nowrap;}
.nav-search-btn:hover{color:#fff;border-color:var(--border2);}
.nav-status-dot{width:7px;height:7px;background:var(--success);border-radius:50%;animation:pulseDot 2s infinite;flex-shrink:0;}
@keyframes pulseDot{0%,100%{box-shadow:0 0 0 0 rgba(34,197,94,0.5);}50%{box-shadow:0 0 0 5px rgba(34,197,94,0);}}
.nav-hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:8px;border:1px solid var(--border);border-radius:6px;}
.nav-hamburger span{display:block;width:20px;height:2px;background:var(--text-secondary);transition:0.3s;}
.nav-hamburger.open span:nth-child(1){transform:translateY(7px) rotate(45deg);}
.nav-hamburger.open span:nth-child(2){opacity:0;}
.nav-hamburger.open span:nth-child(3){transform:translateY(-7px) rotate(-45deg);}
.mobile-menu{display:none;background:var(--deep);border-bottom:1px solid var(--border);padding:20px 24px;}
.mobile-menu.open{display:block;}
.mobile-menu-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:16px;}
.mobile-menu-link{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;letter-spacing:1px;padding:10px 14px;border:1px solid var(--border);border-radius:6px;text-transform:uppercase;transition:0.2s;display:block;text-align:center;}
.mobile-menu-link:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.mobile-menu-link.mm-upgrade{background:var(--accent);color:#000;border-color:var(--accent);}

/* ── SEARCH OVERLAY ───────────────────────────────── */
.search-overlay{position:fixed;inset:0;background:rgba(6,8,13,0.96);z-index:10000;display:none;align-items:flex-start;justify-content:center;padding-top:120px;}
.search-overlay.open{display:flex;}
.search-overlay-inner{width:100%;max-width:700px;padding:0 24px;}
.search-box{display:flex;align-items:center;gap:12px;background:var(--surface);border:2px solid var(--accent);border-radius:12px;padding:16px 20px;margin-bottom:16px;}
.search-box input{flex:1;background:none;border:none;color:#fff;font-size:18px;font-family:'Inter',sans-serif;outline:none;}
.search-box input::placeholder{color:var(--text-muted);}
.search-close{color:var(--text-muted);font-size:24px;cursor:pointer;transition:0.2s;flex-shrink:0;}
.search-close:hover{color:#fff;}
.search-hint{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:1px;text-align:center;}

/* ── BREADCRUMB ───────────────────────────────────── */
.cdb-breadcrumb{background:linear-gradient(90deg,var(--deep),rgba(8,12,21,0.8));border-bottom:1px solid var(--border);padding:10px 24px;}
.breadcrumb-inner{max-width:1500px;margin:0 auto;display:flex;align-items:center;gap:8px;font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--text-muted);flex-wrap:wrap;}
.breadcrumb-inner a{color:var(--text-secondary);transition:0.2s;}
.breadcrumb-inner a:hover{color:var(--accent);}
.breadcrumb-sep{opacity:0.3;}
.breadcrumb-current{color:var(--accent);}

/* ── CATEGORY PAGE HEADER ─────────────────────────── */
.category-header{background:linear-gradient(135deg,var(--deep),#0a0f1e);border-bottom:1px solid var(--border);padding:40px 24px;position:relative;overflow:hidden;}
.category-header::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));}
.category-header-inner{max-width:1500px;margin:0 auto;}
.cat-eyebrow{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:3px;text-transform:uppercase;margin-bottom:10px;}
.cat-title{color:#fff;font-family:'Outfit',sans-serif;font-size:clamp(22px,3vw,40px);font-weight:900;margin-bottom:8px;}
.cat-desc{color:var(--text-secondary);font-size:15px;max-width:640px;}

/* ── HERO ─────────────────────────────────────────── */
.cdb-hero{background:linear-gradient(135deg,#06080d 0%,#080e1c 40%,#060d18 100%);border-bottom:1px solid var(--border);padding:64px 24px 52px;position:relative;overflow:hidden;}
.hero-bg-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(30,41,59,0.5) 1px,transparent 1px),linear-gradient(90deg,rgba(30,41,59,0.5) 1px,transparent 1px);background-size:64px 64px;opacity:0.12;pointer-events:none;}
.hero-bg-glow{position:absolute;top:-120px;left:50%;transform:translateX(-50%);width:800px;height:600px;background:radial-gradient(ellipse,rgba(0,229,195,0.07) 0%,transparent 70%);pointer-events:none;}
.hero-bg-glow2{position:absolute;bottom:-100px;right:-100px;width:500px;height:400px;background:radial-gradient(ellipse,rgba(139,92,246,0.05) 0%,transparent 70%);pointer-events:none;}
.hero-inner{max-width:1200px;margin:0 auto;position:relative;text-align:center;}
.hero-badge{display:inline-flex;align-items:center;gap:8px;border:1px solid rgba(0,229,195,0.2);background:rgba(0,229,195,0.06);border-radius:24px;padding:6px 18px;margin-bottom:28px;backdrop-filter:blur(8px);}
.hero-badge-dot{width:6px;height:6px;background:var(--accent);border-radius:50%;animation:pulseDot 2s infinite;}
.hero-badge-text{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;}
.hero-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:clamp(28px,4.5vw,58px);line-height:1.08;letter-spacing:-1.5px;margin-bottom:18px;}
.hero-title .hl{background:linear-gradient(135deg,var(--accent),var(--accent2));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}
.hero-subtitle{color:var(--text-secondary);font-size:17px;max-width:720px;margin:0 auto 40px;line-height:1.75;}
.hero-cta-row{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin-bottom:52px;}
.hero-btn{display:inline-flex;align-items:center;gap:8px;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:11px;letter-spacing:1.5px;text-transform:uppercase;padding:15px 26px;border-radius:8px;transition:var(--transition);border:1px solid;}
.hero-btn-primary{background:linear-gradient(135deg,var(--accent),#00c4a7);color:#000;border-color:var(--accent);box-shadow:0 0 24px rgba(0,229,195,0.25);}
.hero-btn-primary:hover{box-shadow:0 0 40px rgba(0,229,195,0.5);transform:translateY(-2px);}
.hero-btn-secondary{background:transparent;color:var(--accent2);border-color:rgba(14,165,233,0.35);}
.hero-btn-secondary:hover{background:var(--accent2-dim);border-color:var(--accent2);transform:translateY(-2px);}
.hero-btn-ghost{background:rgba(255,255,255,0.04);color:var(--text-secondary);border-color:var(--border2);}
.hero-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);background:rgba(255,255,255,0.08);}
.platform-cards{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;max-width:1100px;margin:0 auto 52px;}
.platform-card{background:var(--glass);border:1px solid var(--border);border-radius:12px;padding:18px 14px;text-align:left;transition:var(--transition);display:block;position:relative;overflow:hidden;backdrop-filter:blur(8px);}
.platform-card::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(255,255,255,0.02),transparent);pointer-events:none;}
.platform-card:hover{transform:translateY(-5px);border-color:var(--accent);box-shadow:var(--glow);}
.platform-card.blue:hover{border-color:var(--accent2);box-shadow:var(--glow2);}
.platform-card.amber:hover{border-color:var(--accent3);box-shadow:0 0 30px rgba(245,158,11,0.15);}
.platform-card.purple:hover{border-color:var(--accent4);box-shadow:var(--glow4);}
.pc-icon{font-size:24px;margin-bottom:12px;display:block;}
.pc-name{color:#fff;font-family:'Outfit',sans-serif;font-weight:700;font-size:13px;margin-bottom:4px;}
.pc-desc{color:var(--text-muted);font-size:11px;line-height:1.5;}
.pc-tag{display:inline-block;margin-top:10px;color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:1px;text-transform:uppercase;border:1px solid var(--accent-dim);padding:2px 7px;border-radius:3px;background:var(--accent-dim);}
.pc-tag.blue{color:var(--accent2);border-color:rgba(14,165,233,0.2);background:var(--accent2-dim);}
.pc-tag.amber{color:var(--accent3);border-color:rgba(245,158,11,0.2);background:rgba(245,158,11,0.08);}
.pc-tag.purple{color:var(--accent4);border-color:rgba(139,92,246,0.2);background:var(--accent4-dim);}
.hero-stats-row{display:flex;align-items:center;justify-content:center;gap:40px;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:32px;}
.hero-stat{text-align:center;}
.hero-stat-num{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:26px;line-height:1;}
.hero-stat-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-top:6px;}

/* ── LIVE INTEL BANNER ────────────────────────────── */
.live-intel-banner{background:linear-gradient(135deg,#06080d,#0a0f1e);border:1px solid var(--border2);border-radius:16px;padding:28px;margin-bottom:28px;position:relative;overflow:hidden;}
.live-intel-banner::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));}
.lib-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:10px;}
.lib-title{color:#fff;font-family:'JetBrains Mono',monospace;font-weight:900;font-size:11px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:8px;}
.lib-live-dot{width:8px;height:8px;background:var(--accent);border-radius:50%;animation:pulseDot 1.5s infinite;flex-shrink:0;}
.lib-cta{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;border:1px solid var(--accent-dim);padding:7px 16px;border-radius:5px;transition:var(--transition);background:var(--accent-dim);}
.lib-cta:hover{background:var(--accent);color:#000;}
.lib-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;}
.lib-item{background:rgba(15,21,33,0.8);border:1px solid var(--border);border-radius:10px;padding:16px;transition:var(--transition);cursor:default;}
.lib-item:hover{border-color:var(--accent);background:rgba(0,229,195,0.04);}
.lib-item.red .lib-item-label{color:var(--danger);}
.lib-item.blue .lib-item-label{color:var(--accent2);}
.lib-item.amber .lib-item-label{color:var(--accent3);}
.lib-item-label{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;margin-bottom:7px;}
.lib-item-value{color:#fff;font-size:13px;font-weight:600;line-height:1.4;}
.lib-item-sub{color:var(--text-muted);font-size:11px;margin-top:4px;font-family:'JetBrains Mono',monospace;}
@keyframes blink{0%,100%{opacity:1;}50%{opacity:0.2;}}

/* ── SECTION LABELS ───────────────────────────────── */
.section-eyebrow{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:3px;text-transform:uppercase;margin-bottom:20px;display:flex;align-items:center;gap:10px;}
.section-eyebrow::after{content:'';flex:1;height:1px;background:linear-gradient(90deg,var(--border2),transparent);}
.section-eyebrow.blue{color:var(--accent2);}
.section-eyebrow.amber{color:var(--accent3);}
.section-eyebrow.purple{color:var(--accent4);}

/* ── AD UNIT ──────────────────────────────────────── */
.ad-unit{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;margin-bottom:24px;}
.ad-unit-label{color:var(--text-dim);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;padding:6px 16px;border-bottom:1px solid var(--border);text-align:center;}
.ad-unit-inner{padding:12px;text-align:center;}

/* ── ECO STRIP ────────────────────────────────────── */
.eco-ad-strip{background:linear-gradient(135deg,rgba(0,229,195,0.05),rgba(14,165,233,0.05));border:1px solid var(--border2);border-left:3px solid var(--accent);border-radius:12px;padding:22px 26px;margin-bottom:24px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;}
.eas-left{flex:1;}
.eas-eyebrow{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;margin-bottom:5px;}
.eas-title{color:#fff;font-size:15px;font-weight:700;margin-bottom:3px;}
.eas-desc{color:var(--text-muted);font-size:12px;}
.eas-right{display:flex;gap:8px;align-items:center;flex-shrink:0;flex-wrap:wrap;}
.eas-btn{font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:9px 16px;border-radius:6px;border:1px solid;transition:var(--transition);white-space:nowrap;}
.eas-btn-primary{background:var(--accent);color:#000;border-color:var(--accent);}
.eas-btn-primary:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.eas-btn-ghost{color:var(--text-secondary);border-color:var(--border);}
.eas-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);}

/* ── MAIN LAYOUT ──────────────────────────────────── */
.cdb-main-wrap{max-width:1500px;margin:36px auto;padding:0 24px;display:flex;gap:48px;}
main{flex:1;min-width:0;}

/* ── POST CARD GRID (List View) ───────────────────── */
.posts-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:24px;}
.post-card{background:var(--card2);border:1px solid var(--border);border-radius:16px;overflow:hidden;transition:var(--transition);display:flex;flex-direction:column;position:relative;}
.post-card:hover{transform:translateY(-4px);border-color:var(--border2);box-shadow:0 12px 40px rgba(0,0,0,0.4);}
.post-card-featured{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;align-items:stretch;}
.post-card-featured .post-card-img-wrap{aspect-ratio:auto;min-height:280px;}
.post-card-featured .post-card-body{padding:36px;}
.post-card-img-wrap{position:relative;overflow:hidden;aspect-ratio:16/9;background:var(--surface);}
.post-card-img-wrap img{width:100%;height:100%;object-fit:cover;transition:transform 0.5s ease;display:block;}
.post-card:hover .post-card-img-wrap img{transform:scale(1.04);}
.post-card-img-placeholder{width:100%;height:100%;background:linear-gradient(135deg,var(--surface),var(--card));display:flex;align-items:center;justify-content:center;font-size:40px;}
.post-card-featured-badge{position:absolute;top:12px;left:12px;background:linear-gradient(135deg,var(--accent3),#e8890d);color:#000;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;padding:4px 10px;border-radius:4px;z-index:2;}
.post-card-body{padding:22px;flex:1;display:flex;flex-direction:column;}
.post-card-labels{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:12px;}
.post-card-label{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:3px 8px;border-radius:3px;border:1px solid;}
.post-card-label.l-cve,.post-card-label.l-zero-day{color:var(--danger);border-color:rgba(239,68,68,0.25);background:var(--danger-dim);}
.post-card-label.l-ai-security,.post-card-label.l-ai-threat{color:var(--accent4);border-color:rgba(139,92,246,0.25);background:var(--accent4-dim);}
.post-card-label.l-ransomware,.post-card-label.l-malware{color:var(--accent3);border-color:rgba(245,158,11,0.25);background:rgba(245,158,11,0.08);}
.post-card-label.l-default{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.post-card-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:17px;line-height:1.35;margin-bottom:10px;transition:0.2s;}
.post-card-featured .post-card-title{font-size:24px;}
.post-card:hover .post-card-title{color:var(--accent);}
.post-card-snippet{color:var(--text-secondary);font-size:13px;line-height:1.7;margin-bottom:16px;flex:1;}
.post-card-meta{display:flex;align-items:center;justify-content:space-between;padding-top:14px;border-top:1px solid var(--border);flex-wrap:wrap;gap:8px;}
.post-card-date{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;}
.post-card-read{display:inline-flex;align-items:center;gap:6px;color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;transition:0.2s;}
.post-card-read:hover{color:#fff;}

/* ── SINGLE ARTICLE ───────────────────────────────── */
article.single-post{background:var(--card2);padding:48px;border-radius:18px;border:1px solid var(--border);margin-bottom:24px;position:relative;overflow:hidden;}
article.single-post::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border2),transparent);}
.post-hero-wrap{margin:-48px -48px 36px;position:relative;overflow:hidden;max-height:460px;}
.post-hero-wrap img{width:100%;height:460px;object-fit:cover;display:block;}
.post-hero-overlay{position:absolute;bottom:0;left:0;right:0;height:60%;background:linear-gradient(transparent,rgba(13,20,32,0.95));pointer-events:none;}
.post-meta-line{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:1px;margin-bottom:16px;display:flex;flex-wrap:wrap;gap:10px;align-items:center;}
.post-label-tag{color:var(--accent);border:1px solid var(--accent-dim);background:var(--accent-dim);padding:3px 9px;border-radius:3px;font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:1px;}
.post-label-tag.red{color:var(--danger);border-color:var(--danger-dim);background:var(--danger-dim);}
.post-label-tag.amber{color:var(--accent3);border-color:rgba(245,158,11,0.2);background:rgba(245,158,11,0.08);}
.post-label-tag.blue{color:var(--accent2);border-color:var(--accent2-dim);background:var(--accent2-dim);}
.post-label-tag.purple{color:var(--accent4);border-color:var(--accent4-dim);background:var(--accent4-dim);}
h1.post-title{color:#fff;font-size:clamp(22px,3vw,36px);font-weight:900;margin:0 0 24px;font-family:'Outfit',sans-serif;line-height:1.2;letter-spacing:-0.5px;}

/* ── POST BODY ────────────────────────────────────── */
.post-body{color:#cbd5e1;font-size:16px;line-height:1.95;}
.post-body h2{color:#fff;font-family:'Outfit',sans-serif;font-size:22px;font-weight:800;margin:40px 0 14px;padding-bottom:10px;border-bottom:1px solid var(--border);}
.post-body h3{color:#e2e8f0;font-family:'Outfit',sans-serif;font-size:18px;font-weight:700;margin:30px 0 12px;}
.post-body h4{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:12px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;margin:24px 0 10px;}
.post-body p{margin-bottom:18px;}
.post-body ul,.post-body ol{padding-left:24px;margin-bottom:18px;}
.post-body li{margin-bottom:8px;}
.post-body code{background:rgba(0,229,195,0.08);color:var(--accent);padding:2px 7px;border-radius:4px;font-family:'JetBrains Mono',monospace;font-size:13px;border:1px solid rgba(0,229,195,0.15);}
.post-body pre{background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:22px;overflow-x:auto;margin:22px 0;position:relative;}
.post-body pre code{background:none;padding:0;color:#e2e8f0;border:none;font-size:13px;line-height:1.7;}
.post-body a{color:var(--accent2);border-bottom:1px solid rgba(14,165,233,0.25);transition:0.2s;}
.post-body a:hover{color:#fff;border-bottom-color:var(--accent2);}
.post-body blockquote{border-left:3px solid var(--accent);background:rgba(0,229,195,0.04);padding:18px 22px;border-radius:0 10px 10px 0;margin:22px 0;color:var(--text-secondary);}
.post-body table{width:100%;border-collapse:collapse;margin:22px 0;font-size:14px;}
.post-body th{background:var(--surface);color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;padding:12px 14px;border:1px solid var(--border);text-align:left;}
.post-body td{padding:10px 14px;border:1px solid var(--border);color:#cbd5e1;}
.post-body tr:nth-child(even) td{background:rgba(15,21,33,0.5);}

/* ── CODE COPY BUTTON ─────────────────────────────── */
.copy-btn{position:absolute;top:10px;right:10px;background:var(--card);border:1px solid var(--border);color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:1px;text-transform:uppercase;padding:5px 10px;border-radius:4px;cursor:pointer;transition:0.2s;z-index:2;}
.copy-btn:hover{color:var(--accent);border-color:var(--accent-dim);}
.copy-btn.copied{color:var(--success);border-color:rgba(34,197,94,0.3);}

/* ── AUTO TOC ─────────────────────────────────────── */
.auto-toc{background:var(--surface);border:1px solid var(--border);border-left:3px solid var(--accent);border-radius:12px;padding:22px 24px;margin:32px 0;display:none;}
.auto-toc.has-headings{display:block;}
.auto-toc-title{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;display:flex;align-items:center;gap:8px;}
.auto-toc ol{padding-left:20px;}
.auto-toc li{margin-bottom:6px;}
.auto-toc a{color:var(--text-secondary);font-size:13px;transition:0.2s;border-bottom:none;}
.auto-toc a:hover{color:var(--accent);border-bottom:none;}
.auto-toc .toc-h3{padding-left:16px;font-size:12px;}

/* ── CVE CALLOUT ──────────────────────────────────── */
.cve-box{background:linear-gradient(135deg,rgba(239,68,68,0.07),rgba(239,68,68,0.02));border:1px solid rgba(239,68,68,0.2);border-left:3px solid var(--danger);border-radius:12px;padding:22px 26px;margin:26px 0;}
.cve-box-header{display:flex;align-items:center;gap:12px;margin-bottom:10px;}
.cve-box-badge{background:var(--danger);color:#fff;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:900;letter-spacing:1px;padding:3px 10px;border-radius:4px;text-transform:uppercase;}
.cve-box-id{color:#fff;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:14px;}
.cve-box-cvss{color:var(--danger);font-family:'JetBrains Mono',monospace;font-size:12px;font-weight:700;margin-left:auto;}
.cve-box-desc{color:var(--text-secondary);font-size:14px;line-height:1.7;}

/* ── SHARE BUTTONS ────────────────────────────────── */
.share-row{display:flex;align-items:center;gap:10px;margin:28px 0;padding:20px;background:var(--surface);border:1px solid var(--border);border-radius:12px;flex-wrap:wrap;}
.share-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;flex-shrink:0;}
.share-btn{display:inline-flex;align-items:center;gap:7px;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:8px 14px;border-radius:6px;border:1px solid;transition:var(--transition);cursor:pointer;white-space:nowrap;}
.share-btn.twitter{color:#1d9bf0;border-color:rgba(29,155,240,0.25);background:rgba(29,155,240,0.06);}
.share-btn.twitter:hover{background:rgba(29,155,240,0.15);border-color:rgba(29,155,240,0.4);}
.share-btn.linkedin{color:#0a66c2;border-color:rgba(10,102,194,0.25);background:rgba(10,102,194,0.06);}
.share-btn.linkedin:hover{background:rgba(10,102,194,0.15);border-color:rgba(10,102,194,0.4);}
.share-btn.copy{color:var(--text-muted);border-color:var(--border);background:var(--card);}
.share-btn.copy:hover{color:var(--accent);border-color:var(--accent-dim);}
.share-btn.copy.copied{color:var(--success);border-color:rgba(34,197,94,0.3);}

/* ── AUTHOR E-E-A-T BOX ───────────────────────────── */
.author-eeeat-box{background:linear-gradient(135deg,var(--surface),rgba(0,229,195,0.03));border:1px solid var(--border2);border-radius:16px;padding:30px;margin:36px 0;display:flex;gap:22px;align-items:flex-start;position:relative;overflow:hidden;}
.author-eeeat-box::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2));}
.author-eeeat-avatar-placeholder{width:76px;height:76px;border-radius:50%;border:2px solid var(--accent);flex-shrink:0;background:linear-gradient(135deg,var(--card),var(--surface));display:flex;align-items:center;justify-content:center;font-size:30px;box-shadow:0 0 20px rgba(0,229,195,0.2);}
.author-eeeat-body{flex:1;min-width:0;}
.author-eeeat-name{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:17px;margin-bottom:2px;}
.author-eeeat-title{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-bottom:12px;}
.author-eeeat-bio{color:var(--text-secondary);font-size:13px;line-height:1.75;margin-bottom:14px;}
.author-eeeat-creds{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px;}
.author-cred-chip{background:var(--accent-dim);border:1px solid rgba(0,229,195,0.15);color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:4px 9px;border-radius:4px;}
.author-cred-chip.blue{background:var(--accent2-dim);border-color:rgba(14,165,233,0.15);color:var(--accent2);}
.author-cred-chip.purple{background:var(--accent4-dim);border-color:rgba(139,92,246,0.15);color:var(--accent4);}
.author-eeeat-links{display:flex;gap:8px;flex-wrap:wrap;}
.author-eeeat-link{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:7px 13px;border:1px solid var(--border);border-radius:5px;transition:0.2s;}
.author-eeeat-link:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}

/* ── POST TAGS ────────────────────────────────────── */
.post-tags-row{display:flex;flex-wrap:wrap;gap:6px;margin:20px 0;padding-top:20px;border-top:1px solid var(--border);}
.post-tag{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;padding:4px 10px;border:1px solid var(--border);border-radius:4px;transition:0.2s;}
.post-tag:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}

/* ── NEWSLETTER INLINE ────────────────────────────── */
.newsletter-inline{background:linear-gradient(135deg,rgba(0,229,195,0.06),rgba(14,165,233,0.06));border:1px solid var(--border2);border-radius:16px;padding:32px;margin:36px 0;text-align:center;position:relative;overflow:hidden;}
.newsletter-inline::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));}
.nl-eyebrow{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:10px;}
.nl-title{color:#fff;font-family:'Outfit',sans-serif;font-size:20px;font-weight:900;margin-bottom:8px;}
.nl-sub{color:var(--text-secondary);font-size:14px;margin-bottom:20px;}
.nl-form{display:flex;gap:10px;max-width:480px;margin:0 auto;flex-wrap:wrap;}
.nl-input{flex:1;background:var(--surface);border:1px solid var(--border);color:#fff;font-family:'Inter',sans-serif;font-size:14px;padding:12px 16px;border-radius:7px;outline:none;min-width:200px;}
.nl-input:focus{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-dim);}
.nl-input::placeholder{color:var(--text-muted);}
.nl-btn{background:linear-gradient(135deg,var(--accent),#00c4a7);color:#000;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:11px;letter-spacing:1px;text-transform:uppercase;padding:12px 20px;border-radius:7px;border:none;cursor:pointer;transition:var(--transition);white-space:nowrap;}
.nl-btn:hover{box-shadow:0 0 24px rgba(0,229,195,0.4);transform:translateY(-1px);}
.nl-disclaimer{color:var(--text-muted);font-size:11px;margin-top:12px;}

/* ── POST NAVIGATION ──────────────────────────────── */
.post-nav-wrapper{margin-top:48px;border-top:2px solid var(--border);padding-top:36px;}
.post-nav-eyebrow{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:2px;text-transform:uppercase;text-align:center;margin-bottom:18px;}
.post-nav-grid{display:flex;justify-content:space-between;align-items:stretch;gap:12px;}
.nav-btn{color:var(--accent)!important;font-family:'JetBrains Mono',monospace;font-weight:700;text-transform:uppercase;text-decoration:none;font-size:11px;padding:16px 18px;border:1px solid var(--border);border-radius:8px;background:var(--surface);transition:var(--transition);display:flex;align-items:center;gap:10px;flex:1;max-width:44%;}
.nav-btn.nav-newer{justify-content:flex-start;}
.nav-btn.nav-older{justify-content:flex-end;text-align:right;}
.nav-btn:hover{background:var(--accent);color:#000!important;border-color:var(--accent);box-shadow:0 0 25px rgba(0,229,195,0.3);transform:translateY(-2px);}
.nav-btn .nav-arrow{font-size:18px;flex-shrink:0;}
.nav-text-block{display:flex;flex-direction:column;gap:3px;overflow:hidden;}
.nav-eyebrow2{font-size:9px;opacity:0.6;letter-spacing:2px;white-space:nowrap;}
.nav-title2{font-size:11px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:220px;}
.nav-hub-btn{color:var(--text-secondary)!important;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:10px;text-transform:uppercase;text-decoration:none;padding:16px 12px;border:1px solid var(--border);border-radius:8px;background:transparent;transition:0.3s;display:flex;align-items:center;justify-content:center;letter-spacing:1px;white-space:nowrap;flex-shrink:0;}
.nav-hub-btn:hover{border-color:var(--text-secondary);color:#fff!important;}
.nav-placeholder{flex:1;max-width:44%;}

/* ── PAGINATION ───────────────────────────────────── */
.cdb-pagination{display:flex;justify-content:center;align-items:center;gap:8px;padding:32px 0;}
.page-btn{display:inline-flex;align-items:center;gap:8px;color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:11px 20px;border:1px solid var(--border);border-radius:8px;transition:var(--transition);background:var(--surface);}
.page-btn:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.page-btn.newer-btn{color:var(--accent2);border-color:var(--accent2-dim);}
.page-btn.older-btn{background:var(--accent-dim);color:var(--accent);border-color:var(--accent-dim);}

/* ── SIDEBAR ──────────────────────────────────────── */
.matrix-sidebar{width:320px;flex-shrink:0;position:sticky;top:70px;align-self:flex-start;display:flex;flex-direction:column;gap:18px;max-height:calc(100vh - 90px);overflow-y:auto;scrollbar-width:none;}
.matrix-sidebar::-webkit-scrollbar{display:none;}
.sidebar-module{background:var(--glass);border:1px solid var(--border);border-radius:14px;padding:20px;overflow:hidden;position:relative;backdrop-filter:blur(8px);}
.sidebar-module::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border2),transparent);}
.module-title{color:var(--accent);font-family:'JetBrains Mono',monospace;font-weight:900;font-size:9px;letter-spacing:2px;margin-bottom:14px;border-bottom:1px solid var(--border);padding-bottom:10px;text-transform:uppercase;display:flex;align-items:center;justify-content:space-between;}
.module-title.blue{color:var(--accent2);}
.module-title.amber{color:var(--accent3);}
.module-title.purple{color:var(--accent4);}
.eco-link{display:flex;align-items:center;justify-content:space-between;color:#fff;text-decoration:none;font-size:12px;font-weight:600;margin-bottom:8px;transition:0.2s;padding:8px 10px;border-radius:7px;border:1px solid transparent;}
.eco-link:last-child{margin-bottom:0;}
.eco-link:hover{color:var(--accent);background:var(--accent-dim);border-color:rgba(0,229,195,0.1);}
.eco-link .el-arrow{font-size:10px;opacity:0.4;transition:0.2s;}
.eco-link:hover .el-arrow{opacity:1;transform:translateX(2px);}
.eco-link .el-badge{font-size:9px;background:var(--accent);color:#000;padding:1px 6px;border-radius:3px;font-family:'JetBrains Mono',monospace;font-weight:700;}
.eco-link .el-badge.blue{background:var(--accent2);}

/* ── CVE WIDGET ───────────────────────────────────── */
.cve-widget-item{display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);}
.cve-widget-item:last-child{border-bottom:none;padding-bottom:0;}
.cve-widget-badge{flex-shrink:0;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:900;padding:3px 7px;border-radius:3px;text-transform:uppercase;}
.cve-widget-badge.crit{background:var(--danger);color:#fff;}
.cve-widget-badge.high{background:var(--accent3);color:#000;}
.cwe-widget-badge.med{background:var(--accent2);color:#fff;}
.cve-widget-id{color:#fff;font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;margin-bottom:3px;}
.cve-widget-desc{color:var(--text-muted);font-size:11px;line-height:1.4;}

/* ── MITRE ATT&CK MINI GRID ───────────────────────── */
.mitre-grid{display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:4px;}
.mitre-tactic{background:var(--surface);border:1px solid var(--border);border-radius:5px;padding:6px 8px;cursor:default;transition:0.2s;}
.mitre-tactic:hover{border-color:var(--accent2);background:var(--accent2-dim);}
.mitre-tactic-id{color:var(--accent2);font-family:'JetBrains Mono',monospace;font-size:8px;font-weight:700;letter-spacing:1px;}
.mitre-tactic-name{color:var(--text-secondary);font-size:9px;margin-top:2px;line-height:1.2;}

/* ── SIDEBAR AD CARDS ─────────────────────────────── */
.sidebar-ad-card{border-radius:14px;padding:22px;position:relative;overflow:hidden;text-align:center;}
.sidebar-ad-card.sentinel{background:linear-gradient(135deg,#06080d,#0a1220);border:1px solid rgba(0,229,195,0.2);}
.sidebar-ad-card.tools{background:linear-gradient(135deg,#06080d,#0a1530);border:1px solid rgba(14,165,233,0.2);}
.sidebar-ad-card.api{background:linear-gradient(135deg,#06080d,#120a20);border:1px solid rgba(139,92,246,0.2);}
.sidebar-ad-card.mssp{background:linear-gradient(135deg,#06080d,#1a0d05);border:1px solid rgba(245,158,11,0.2);}
.sac-glow{position:absolute;top:-40px;left:50%;transform:translateX(-50%);width:160px;height:120px;border-radius:50%;pointer-events:none;}
.sac-glow.green{background:radial-gradient(ellipse,rgba(0,229,195,0.15) 0%,transparent 70%);}
.sac-glow.blue{background:radial-gradient(ellipse,rgba(14,165,233,0.15) 0%,transparent 70%);}
.sac-glow.purple{background:radial-gradient(ellipse,rgba(139,92,246,0.15) 0%,transparent 70%);}
.sac-glow.amber{background:radial-gradient(ellipse,rgba(245,158,11,0.15) 0%,transparent 70%);}
.sac-icon{font-size:28px;margin-bottom:10px;display:block;}
.sac-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:14px;margin-bottom:5px;}
.sac-desc{color:var(--text-muted);font-size:11px;line-height:1.5;margin-bottom:14px;}
.sac-features{text-align:left;margin-bottom:14px;}
.sac-feature{color:var(--text-secondary);font-size:11px;padding:3px 0;display:flex;align-items:center;gap:6px;}
.sac-feature::before{content:'✓';color:var(--accent);font-weight:900;font-size:10px;flex-shrink:0;}
.sac-btn{display:block;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:10px 16px;border-radius:7px;border:1px solid;transition:var(--transition);width:100%;text-align:center;}
.sac-btn.green{color:#000;background:linear-gradient(135deg,var(--accent),#00c4a7);border-color:var(--accent);}
.sac-btn.green:hover{box-shadow:0 0 24px rgba(0,229,195,0.4);transform:translateY(-1px);}
.sac-btn.blue{color:#fff;background:var(--accent2);border-color:var(--accent2);}
.sac-btn.blue:hover{box-shadow:0 0 20px rgba(14,165,233,0.4);}
.sac-btn.purple{color:#fff;background:var(--accent4);border-color:var(--accent4);}
.sac-btn.amber{color:#000;background:var(--accent3);border-color:var(--accent3);}
.sac-btn-ghost{display:block;color:var(--text-secondary);border-color:var(--border);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:8px 16px;border-radius:7px;border:1px solid;transition:0.3s;width:100%;text-align:center;margin-top:8px;}
.sac-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);}

/* ── API STATUS ───────────────────────────────────── */
.api-status-row{display:flex;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border);}
.api-status-row:last-of-type{border-bottom:none;}
.api-status-name{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;}
.api-status-badge{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;padding:3px 8px;border-radius:3px;}
.api-status-badge.online{background:rgba(34,197,94,0.12);color:var(--success);}
.api-status-badge.checking{background:rgba(245,158,11,0.12);color:var(--accent3);}

/* ── THREAT GAUGE ─────────────────────────────────── */
.threat-gauge{text-align:center;padding:10px 0;}
.threat-gauge-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;}
.threat-gauge-level{font-family:'Outfit',sans-serif;font-weight:900;font-size:26px;letter-spacing:2px;text-transform:uppercase;}
.threat-gauge-level.high{color:var(--accent3);}
.threat-gauge-level.critical{color:var(--danger);}
.threat-gauge-bar{height:6px;background:var(--border);border-radius:3px;overflow:hidden;margin:10px 0 6px;}
.threat-gauge-fill{height:100%;border-radius:3px;background:linear-gradient(90deg,var(--accent),var(--accent3),var(--danger));box-shadow:0 0 10px rgba(245,158,11,0.3);}
.threat-gauge-sub{color:var(--text-muted);font-size:10px;font-family:'JetBrains Mono',monospace;}

/* ── ENTERPRISE SECTION ───────────────────────────── */
.enterprise-section{background:var(--deep);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:64px 24px;}
.enterprise-inner{max-width:1200px;margin:0 auto;}
.enterprise-header{text-align:center;margin-bottom:48px;}
.enterprise-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:clamp(24px,3vw,40px);margin-bottom:12px;letter-spacing:-0.5px;}
.enterprise-title span{color:var(--accent);}
.enterprise-subtitle{color:var(--text-secondary);font-size:16px;max-width:640px;margin:0 auto;}
.enterprise-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:22px;}
.enterprise-card{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:28px;transition:var(--transition);position:relative;overflow:hidden;}
.enterprise-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;}
.enterprise-card.green::before{background:linear-gradient(90deg,var(--accent),#00bfa3);}
.enterprise-card.blue::before{background:linear-gradient(90deg,var(--accent2),#0284c7);}
.enterprise-card.amber::before{background:linear-gradient(90deg,var(--accent3),#d97706);}
.enterprise-card.purple::before{background:linear-gradient(90deg,var(--accent4),#7c3aed);}
.enterprise-card:hover{transform:translateY(-5px);box-shadow:var(--shadow-lg);}
.enterprise-card.green:hover{box-shadow:0 8px 40px rgba(0,229,195,0.12);}
.enterprise-card.blue:hover{box-shadow:0 8px 40px rgba(14,165,233,0.12);}
.ec-icon{font-size:36px;margin-bottom:16px;}
.ec-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:18px;margin-bottom:10px;}
.ec-desc{color:var(--text-secondary);font-size:13px;line-height:1.75;margin-bottom:18px;}
.ec-features{display:flex;flex-direction:column;gap:6px;margin-bottom:18px;}
.ec-feature{color:var(--text-muted);font-size:12px;display:flex;align-items:center;gap:8px;}
.ec-feature::before{content:'→';font-size:11px;flex-shrink:0;}
.enterprise-card.green .ec-feature::before{color:var(--accent);}
.enterprise-card.blue .ec-feature::before{color:var(--accent2);}
.enterprise-card.amber .ec-feature::before{color:var(--accent3);}
.enterprise-card.purple .ec-feature::before{color:var(--accent4);}
.ec-btn{display:block;text-align:center;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:11px 16px;border-radius:7px;border:1px solid;transition:var(--transition);}
.ec-btn.green{color:#000;background:var(--accent);border-color:var(--accent);}
.ec-btn.green:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.ec-btn.blue{color:#fff;background:var(--accent2);border-color:var(--accent2);}
.ec-btn.amber{color:#000;background:var(--accent3);border-color:var(--accent3);}
.ec-btn.purple{color:#fff;background:var(--accent4);border-color:var(--accent4);}

/* ── FAQ SECTION ──────────────────────────────────── */
.faq-section{background:linear-gradient(135deg,var(--void),#080c18);padding:64px 24px;border-top:1px solid var(--border);}
.faq-inner{max-width:900px;margin:0 auto;}
.faq-list{margin-top:32px;display:flex;flex-direction:column;gap:12px;}
.faq-item{background:var(--surface);border:1px solid var(--border);border-radius:12px;overflow:hidden;transition:var(--transition);}
.faq-item.open{border-color:var(--border2);}
.faq-question{display:flex;align-items:center;justify-content:space-between;padding:20px 24px;cursor:pointer;color:#fff;font-size:15px;font-weight:600;gap:12px;transition:0.2s;}
.faq-question:hover{color:var(--accent);}
.faq-icon{color:var(--accent);font-size:20px;flex-shrink:0;transition:transform 0.3s;font-family:'JetBrains Mono',monospace;line-height:1;}
.faq-item.open .faq-icon{transform:rotate(45deg);}
.faq-answer{color:var(--text-secondary);font-size:14px;line-height:1.8;padding:0 24px 22px;display:none;}
.faq-item.open .faq-answer{display:block;}

/* ── AI SECURITY SECTION ──────────────────────────── */
.ai-security-section{background:linear-gradient(135deg,var(--void),#0a081a);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:64px 24px;}
.ai-security-inner{max-width:1200px;margin:0 auto;}
.ai-security-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:32px;}
.ai-security-card{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:28px;transition:var(--transition);position:relative;overflow:hidden;}
.ai-security-card::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--accent4),transparent);}
.ai-security-card:hover{border-color:var(--accent4);box-shadow:var(--glow4);transform:translateY(-3px);}
.asc-eyebrow{color:var(--accent4);font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:10px;}
.asc-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:17px;margin-bottom:10px;}
.asc-desc{color:var(--text-secondary);font-size:13px;line-height:1.7;margin-bottom:16px;}
.asc-link{color:var(--accent4);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;border:none;}
.asc-link:hover{color:#fff;border:none;}

/* ── MSSP SECTION ─────────────────────────────────── */
.mssp-section{background:var(--deep);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:64px 24px;}
.mssp-inner{max-width:1200px;margin:0 auto;}
.mssp-hero{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center;margin-top:32px;}
.mssp-content-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:clamp(20px,2.5vw,34px);margin-bottom:14px;line-height:1.2;}
.mssp-content-title span{color:var(--accent3);}
.mssp-content-desc{color:var(--text-secondary);font-size:14px;line-height:1.85;margin-bottom:22px;}
.mssp-services-list{display:flex;flex-direction:column;gap:10px;margin-bottom:26px;}
.mssp-service-item{display:flex;align-items:center;gap:14px;padding:14px 18px;background:var(--surface);border:1px solid var(--border);border-radius:10px;transition:0.2s;}
.mssp-service-item:hover{border-color:var(--border2);}
.mssp-service-icon{font-size:20px;flex-shrink:0;}
.mssp-service-name{color:#fff;font-size:13px;font-weight:600;}
.mssp-service-desc{color:var(--text-muted);font-size:11px;}
.mssp-cta-row{display:flex;gap:10px;flex-wrap:wrap;}
.mssp-btn-primary{background:var(--accent3);color:#000;font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:13px 22px;border-radius:7px;border:1px solid var(--accent3);transition:var(--transition);}
.mssp-btn-primary:hover{box-shadow:0 0 25px rgba(245,158,11,0.4);transform:translateY(-2px);}
.mssp-btn-ghost{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:13px 22px;border-radius:7px;border:1px solid var(--border);transition:0.3s;}
.mssp-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);}
.mssp-stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;}
.mssp-stat-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:24px;text-align:center;transition:var(--transition);}
.mssp-stat-card:hover{border-color:var(--border2);}
.mssp-stat-num{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:30px;margin-bottom:5px;}
.mssp-stat-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;}

/* ── DETECTION SECTION ────────────────────────────── */
.detection-section{background:var(--void);padding:64px 24px;}
.detection-inner{max-width:1200px;margin:0 auto;}
.detection-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:32px;}
.detection-card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:24px;transition:var(--transition);text-align:center;position:relative;overflow:hidden;}
.detection-card::before{content:'';position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,transparent,var(--accent2),transparent);opacity:0;transition:0.3s;}
.detection-card:hover{border-color:var(--accent2);transform:translateY(-4px);box-shadow:var(--glow2);}
.detection-card:hover::before{opacity:1;}
.dc-icon{font-size:34px;margin-bottom:14px;}
.dc-count{color:var(--accent2);font-family:'Outfit',sans-serif;font-weight:900;font-size:32px;margin-bottom:5px;}
.dc-label{color:#fff;font-size:14px;font-weight:600;margin-bottom:7px;}
.dc-sub{color:var(--text-muted);font-size:11px;}

/* ── STICKY BOTTOM CTA ────────────────────────────── */
.sticky-cta-bar{position:fixed;bottom:0;left:0;right:0;z-index:998;background:linear-gradient(90deg,rgba(6,8,13,0.98),rgba(8,12,21,0.98));border-top:1px solid var(--border);padding:12px 24px;display:flex;align-items:center;justify-content:space-between;gap:16px;backdrop-filter:blur(20px);transform:translateY(0);transition:transform 0.4s ease;}
.sticky-cta-bar.hidden{transform:translateY(100%);}
.scb-left{display:flex;align-items:center;gap:12px;}
.scb-dot{width:8px;height:8px;background:var(--accent);border-radius:50%;animation:pulseDot 2s infinite;flex-shrink:0;}
.scb-text{color:#fff;font-size:13px;font-weight:600;}
.scb-sub{color:var(--text-muted);font-size:11px;}
.scb-right{display:flex;align-items:center;gap:8px;}
.scb-btn{font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:9px 16px;border-radius:6px;border:1px solid;transition:var(--transition);white-space:nowrap;cursor:pointer;}
.scb-btn-primary{background:var(--accent);color:#000;border-color:var(--accent);}
.scb-btn-primary:hover{background:#00ffdc;}
.scb-btn-ghost{color:var(--text-muted);border-color:var(--border);background:none;}
.scb-btn-ghost:hover{color:#fff;}
.scb-close{color:var(--text-muted);cursor:pointer;font-size:18px;padding:4px 8px;transition:0.2s;flex-shrink:0;}
.scb-close:hover{color:#fff;}

/* ── FOOTER ───────────────────────────────────────── */
.cdb-footer{background:var(--deep);border-top:2px solid var(--border);margin-top:60px;}
.footer-nl-strip{background:linear-gradient(135deg,rgba(0,229,195,0.05),rgba(14,165,233,0.04));border-bottom:1px solid var(--border);padding:36px 24px;}
.footer-nl-inner{max-width:900px;margin:0 auto;text-align:center;}
.fnl-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:20px;margin-bottom:6px;}
.fnl-sub{color:var(--text-secondary);font-size:13px;margin-bottom:20px;}
.fnl-form{display:flex;gap:10px;max-width:480px;margin:0 auto;flex-wrap:wrap;justify-content:center;}
.fnl-input{flex:1;min-width:200px;background:var(--surface);border:1px solid var(--border);color:#fff;font-family:'Inter',sans-serif;font-size:14px;padding:12px 16px;border-radius:7px;outline:none;}
.fnl-input:focus{border-color:var(--accent);}
.fnl-btn{background:linear-gradient(135deg,var(--accent),#00c4a7);color:#000;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:11px;letter-spacing:1px;text-transform:uppercase;padding:12px 22px;border-radius:7px;border:none;cursor:pointer;transition:var(--transition);}
.fnl-btn:hover{box-shadow:0 0 20px rgba(0,229,195,0.4);}
.footer-eco-banner{border-bottom:1px solid var(--border);padding:44px 24px;}
.feb-inner{max-width:1200px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap;}
.feb-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:24px;margin-bottom:8px;}
.feb-title span{color:var(--accent);}
.feb-sub{color:var(--text-secondary);font-size:14px;margin-bottom:16px;}
.feb-platforms{display:flex;flex-wrap:wrap;gap:8px;}
.feb-platform-chip{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:6px 12px;border:1px solid var(--border);border-radius:5px;transition:0.2s;}
.feb-platform-chip:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.feb-cta-col{display:flex;flex-direction:column;gap:8px;flex-shrink:0;}
.feb-btn{font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:12px 22px;border-radius:6px;border:1px solid;transition:var(--transition);text-align:center;white-space:nowrap;}
.feb-btn-primary{background:var(--accent);color:#000;border-color:var(--accent);}
.feb-btn-primary:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.feb-btn-secondary{color:var(--accent3);border-color:rgba(245,158,11,0.3);}
.feb-btn-secondary:hover{background:rgba(245,158,11,0.06);}
.footer-grid{max-width:1200px;margin:0 auto;padding:52px 24px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:32px;}
.footer-brand-name{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:21px;letter-spacing:0.5px;margin-bottom:4px;}
.footer-brand-tagline{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;}
.footer-brand-desc{color:var(--text-muted);font-size:12px;line-height:1.75;margin-bottom:16px;}
.footer-social-row{display:flex;flex-wrap:wrap;gap:8px;}
.footer-social-link{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;padding:5px 10px;border:1px solid var(--border);border-radius:4px;transition:0.2s;}
.footer-social-link:hover{color:var(--accent);border-color:var(--accent-dim);}
.footer-col-title{color:#fff;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid var(--border);}
.footer-link{display:block;color:var(--text-muted);font-size:12px;margin-bottom:8px;transition:0.2s;}
.footer-link:hover{color:var(--accent);}
.footer-bottom{background:var(--void);border-top:1px solid var(--border);padding:16px 24px;}
.footer-bottom-inner{max-width:1200px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;}
.footer-copyright{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;}
.footer-bottom-links{display:flex;gap:16px;}
.footer-bottom-link{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;transition:0.2s;}
.footer-bottom-link:hover{color:var(--accent);}

/* ── UTILITY ──────────────────────────────────────── */
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;}
.truncate{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.counter-num{transition:0.05s;}

/* ── RESPONSIVE ───────────────────────────────────── */
@media(max-width:1280px){
  .platform-cards{grid-template-columns:repeat(3,1fr);}
  .footer-grid{grid-template-columns:1fr 1fr 1fr;}
  .ai-security-grid{grid-template-columns:1fr 1fr;}
  .mssp-hero{grid-template-columns:1fr;}
}
@media(max-width:1024px){
  .platform-cards{grid-template-columns:repeat(3,1fr);}
  .footer-grid{grid-template-columns:1fr 1fr;}
  .ai-security-grid{grid-template-columns:1fr;}
}
@media(max-width:900px){
  .cdb-main-wrap{flex-direction:column;gap:28px;}
  .matrix-sidebar{width:100%;position:static;max-height:none;}
  .nav-links{display:none;}
  .nav-cta-group .nav-link:not(.highlight){display:none;}
  .nav-hamburger{display:flex;}
  article.single-post{padding:28px 20px;}
  .post-hero-wrap{margin:-28px -20px 28px;}
  .post-hero-wrap img{height:280px;}
  .author-eeeat-box{flex-direction:column;align-items:center;text-align:center;}
  .author-eeeat-links{justify-content:center;}
  .hero-stats-row{gap:24px;}
  .post-nav-grid{flex-direction:column;}
  .nav-btn{max-width:100%;}
  .posts-grid{grid-template-columns:1fr;}
  .post-card-featured{grid-template-columns:1fr;}
  .post-card-featured .post-card-img-wrap{min-height:220px;}
  .feb-inner{flex-direction:column;text-align:center;}
  .feb-platforms{justify-content:center;}
  .feb-cta-col{flex-direction:row;flex-wrap:wrap;justify-content:center;}
  .sticky-cta-bar .scb-text{display:none;}
  .mssp-hero{grid-template-columns:1fr;}
}
@media(max-width:600px){
  .footer-grid{grid-template-columns:1fr;}
  .platform-cards{grid-template-columns:1fr 1fr;}
  .hero-cta-row{flex-direction:column;align-items:stretch;}
  .hero-btn{justify-content:center;}
  .nl-form{flex-direction:column;}
  .mssp-stats-grid{grid-template-columns:1fr 1fr;}
  .sticky-cta-bar{flex-direction:column;padding:10px 16px;gap:8px;}
}
@media print{
  .cdb-ticker,.cdb-topnav,.mobile-menu,.matrix-sidebar,.cdb-footer,.eco-ad-strip,.newsletter-inline,.ad-unit,.sticky-cta-bar{display:none!important;}
  body{background:#fff;color:#000;}
  article.single-post{border:none;padding:0;}
  h1.post-title,.post-body h2,.post-body h3{color:#000;}
  .post-body{color:#333;}
}

/* ── Post card upgrades ── */
.posts-grid>.single-post{grid-column:1/-1;width:100%;}
.post-card-img-wrap{position:relative;overflow:hidden;aspect-ratio:16/9;background:linear-gradient(135deg,#0d1420 0%,#091422 100%);}
.post-card-img-wrap img{width:100%;height:100%;object-fit:cover;transition:transform 0.5s ease;display:block;}
.post-card:hover .post-card-img-wrap img{transform:scale(1.04);}
.post-card-img-canvas{width:100%;height:100%;display:block;position:absolute;top:0;left:0;}
.post-card-img-placeholder{display:none;}/* hidden – JS generates banner */
/* Featured card */
.post-card-featured{grid-column:1/-1;display:grid;grid-template-columns:1.2fr 1fr;align-items:stretch;}
.post-card-featured .post-card-img-wrap{aspect-ratio:auto;min-height:300px;}
.post-card-featured .post-card-body{padding:40px;}
.post-card-featured .post-card-title{font-size:26px;line-height:1.25;}

/* ── Breaking / Trending badges ── */
.card-urgency-badge{position:absolute;top:12px;right:12px;z-index:3;font-family:'JetBrains Mono',monospace;font-size:8px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;padding:4px 10px;border-radius:4px;}
.badge-breaking{background:#ef4444;color:#fff;animation:pulseBadge 1.5s infinite;}
.badge-zeroday{background:linear-gradient(135deg,#dc2626,#991b1b);color:#fff;animation:pulseBadge 1.5s infinite;}
.badge-trending{background:linear-gradient(135deg,#f59e0b,#d97706);color:#000;}
.badge-new{background:linear-gradient(135deg,#00f5ff,#00bcd4);color:#000;}
.badge-hot{background:linear-gradient(135deg,#f97316,#ea580c);color:#fff;}
@keyframes pulseBadge{0%,100%{opacity:1}50%{opacity:0.7}}

/* ── Commercial label colors ── */
.post-card-label.l-threat-intelligence{color:#00f5ff;border-color:rgba(0,245,255,0.25);background:rgba(0,245,255,0.06);}
.post-card-label.l-vulnerabilities,.post-card-label.l-vulnerability{color:#ef4444;border-color:rgba(239,68,68,0.25);background:rgba(239,68,68,0.06);}
.post-card-label.l-cve,.post-card-label.l-zero-day,.post-card-label.l-zero-days{color:#ef4444;border-color:rgba(239,68,68,0.3);background:rgba(239,68,68,0.1);}
.post-card-label.l-ransomware{color:#f59e0b;border-color:rgba(245,158,11,0.3);background:rgba(245,158,11,0.08);}
.post-card-label.l-malware{color:#f97316;border-color:rgba(249,115,22,0.25);background:rgba(249,115,22,0.06);}
.post-card-label.l-ai-security,.post-card-label.l-ai-threat{color:#a78bfa;border-color:rgba(139,92,246,0.3);background:rgba(139,92,246,0.08);}
.post-card-label.l-default{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}

/* ── Enhanced card body ── */
.post-card-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:17px;line-height:1.35;margin-bottom:10px;transition:0.2s;}
.post-card:hover .post-card-title{color:var(--accent);}
.post-card-snippet{color:var(--text-secondary);font-size:13px;line-height:1.7;margin-bottom:16px;flex:1;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;}
.post-card-meta{display:flex;align-items:center;justify-content:space-between;padding-top:14px;border-top:1px solid var(--border);flex-wrap:wrap;gap:8px;}
.post-card-date{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;}
.post-card-read{display:inline-flex;align-items:center;gap:6px;color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;transition:0.2s;background:var(--accent-dim);border:1px solid var(--accent-dim);border-radius:4px;padding:5px 12px;}
.post-card-read:hover{background:var(--accent);color:#000;}

/* ── Ecosystem promo cards ── */
.eco-promo-card{background:var(--surface);border:1px solid var(--border);border-radius:14px;overflow:hidden;margin-bottom:20px;position:relative;}
.eco-promo-slide{display:none;flex-direction:column;padding:20px;}
.eco-promo-slide.active{display:flex;}
.eco-promo-badge{display:inline-flex;align-items:center;gap:6px;font-family:'JetBrains Mono',monospace;font-size:8px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--accent);border:1px solid var(--accent-dim);border-radius:3px;padding:3px 8px;margin-bottom:12px;width:fit-content;}
.eco-promo-icon{font-size:28px;margin-bottom:8px;}
.eco-promo-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:15px;line-height:1.3;margin-bottom:6px;}
.eco-promo-desc{color:var(--text-secondary);font-size:11px;line-height:1.6;margin-bottom:14px;}
.eco-promo-cta{display:inline-flex;align-items:center;gap:6px;background:linear-gradient(135deg,var(--accent),var(--accent2));color:#000;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;padding:8px 16px;border-radius:6px;text-decoration:none;transition:0.2s;}
.eco-promo-cta:hover{opacity:0.9;transform:translateY(-1px);}
.eco-promo-dots{display:flex;align-items:center;justify-content:center;gap:6px;padding:10px 0;border-top:1px solid var(--border);}
.eco-promo-dot{width:6px;height:6px;border-radius:50%;background:var(--border);cursor:pointer;transition:0.2s;}
.eco-promo-dot.active{background:var(--accent);transform:scale(1.3);}
.eco-promo-glow{position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));animation:shimmer 3s infinite;}
/* Eco strip inline */
.eco-strip-inline{background:linear-gradient(135deg,var(--surface),var(--card));border:1px solid var(--border);border-radius:14px;padding:24px;margin:32px 0;position:relative;overflow:hidden;}
.eco-strip-inline::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));}
.eco-strip-title{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--accent);margin-bottom:16px;}
.eco-strip-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;}
.eco-strip-item{background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:12px;text-align:center;transition:0.2s;text-decoration:none;display:flex;flex-direction:column;align-items:center;gap:6px;}
.eco-strip-item:hover{border-color:var(--accent);transform:translateY(-2px);}
.eco-strip-item-icon{font-size:20px;}
.eco-strip-item-name{font-family:'JetBrains Mono',monospace;font-size:8px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--text-secondary);}
.eco-strip-item-desc{font-size:9px;color:var(--text-muted);line-height:1.4;}
@media(max-width:600px){.eco-strip-grid{grid-template-columns:repeat(2,1fr);}}
@media(max-width:900px){.post-card-featured{grid-template-columns:1fr;}.post-card-featured .post-card-img-wrap{min-height:220px;}}


/* ── Social share bar ── */
.social-share-bar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:24px 0;padding:16px;background:var(--surface);border:1px solid var(--border);border-radius:10px;}
.social-share-label{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--text-muted);margin-right:4px;white-space:nowrap;}
.share-btn{display:inline-flex;align-items:center;gap:6px;padding:7px 14px;border-radius:6px;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;text-decoration:none;transition:0.2s;border:1px solid transparent;cursor:pointer;}
.share-btn:hover{transform:translateY(-1px);filter:brightness(1.1);}
.share-btn-x{background:#000;color:#fff;border-color:#333;}
.share-btn-linkedin{background:#0077b5;color:#fff;}
.share-btn-reddit{background:#ff4500;color:#fff;}
.share-btn-hn{background:#f60;color:#fff;}
.share-btn-copy{background:var(--card);color:var(--accent);border-color:var(--accent-dim);}
.share-btn-copy.copied{background:var(--accent);color:#000;}

/* ── Newsletter inline ── */
.nl-capture{background:linear-gradient(135deg,#0a1628,#061020);border:1px solid rgba(0,245,255,0.2);border-radius:14px;padding:28px;margin:32px 0;position:relative;overflow:hidden;text-align:center;}
.nl-capture::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));}
.nl-capture-eyebrow{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--accent);margin-bottom:8px;}
.nl-capture-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:20px;margin-bottom:6px;}
.nl-capture-sub{color:var(--text-secondary);font-size:13px;margin-bottom:20px;line-height:1.6;}
.nl-capture-row{display:flex;gap:8px;max-width:460px;margin:0 auto;flex-wrap:wrap;justify-content:center;}
.nl-capture-input{flex:1;min-width:200px;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:11px 16px;color:#fff;font-family:'Inter',sans-serif;font-size:13px;outline:none;}
.nl-capture-input:focus{border-color:var(--accent);}
.nl-capture-btn{background:linear-gradient(135deg,var(--accent),var(--accent2));color:#000;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:900;letter-spacing:1.5px;text-transform:uppercase;padding:11px 22px;border-radius:8px;border:none;cursor:pointer;white-space:nowrap;transition:0.2s;}
.nl-capture-btn:hover{opacity:0.9;transform:translateY(-1px);}
.nl-capture-trust{font-size:10px;color:var(--text-muted);margin-top:10px;}

/* ── Affiliate / tools strip ── */
.affiliate-strip{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:18px;margin-bottom:20px;}
.affiliate-strip-title{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--text-muted);margin-bottom:12px;}
.aff-item{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border);text-decoration:none;}
.aff-item:last-child{border-bottom:none;padding-bottom:0;}
.aff-item-icon{font-size:18px;flex-shrink:0;}
.aff-item-body{flex:1;}
.aff-item-name{color:#fff;font-size:12px;font-weight:600;line-height:1.2;}
.aff-item-desc{color:var(--text-muted);font-size:10px;line-height:1.3;}
.aff-item-badge{font-family:'JetBrains Mono',monospace;font-size:8px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:3px 7px;border-radius:3px;white-space:nowrap;}
.aff-badge-free{background:rgba(0,245,255,0.1);color:var(--accent);border:1px solid var(--accent-dim);}
.aff-badge-trial{background:rgba(139,92,246,0.1);color:#a78bfa;border:1px solid rgba(139,92,246,0.2);}

/* ── RSS / subscribe bar ── */
.rss-bar{display:flex;align-items:center;gap:10px;padding:12px 16px;background:var(--surface);border:1px solid var(--border);border-radius:8px;margin-bottom:16px;flex-wrap:wrap;}
.rss-bar-label{color:var(--text-secondary);font-size:11px;flex:1;}
.rss-btn{display:inline-flex;align-items:center;gap:5px;padding:6px 12px;border-radius:5px;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;text-decoration:none;transition:0.2s;}
.rss-btn-feed{background:rgba(245,158,11,0.1);color:#f59e0b;border:1px solid rgba(245,158,11,0.2);}
.rss-btn-news{background:rgba(0,245,255,0.1);color:var(--accent);border:1px solid var(--accent-dim);}
.rss-btn:hover{transform:translateY(-1px);}

/* ── Helpfulness vote ── */
.helpful-widget{display:flex;align-items:center;gap:12px;padding:14px 18px;background:var(--surface);border:1px solid var(--border);border-radius:8px;margin:24px 0;flex-wrap:wrap;}
.helpful-q{color:var(--text-secondary);font-size:12px;flex:1;}
.helpful-btn{padding:7px 18px;border-radius:6px;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;border:1px solid var(--border);background:var(--card);color:var(--text-secondary);cursor:pointer;transition:0.2s;}
.helpful-btn:hover,.helpful-btn.active{background:var(--accent);color:#000;border-color:var(--accent);}
.helpful-btn.no:hover,.helpful-btn.no.active{background:var(--danger);color:#fff;border-color:var(--danger);}

/* ── Breaking alert banner ── */
.breaking-alert{display:flex;align-items:center;gap:10px;padding:10px 16px;background:rgba(239,68,68,0.08);border:1px solid rgba(239,68,68,0.2);border-radius:8px;margin-bottom:16px;}
.breaking-pulse{width:8px;height:8px;border-radius:50%;background:#ef4444;animation:pulseBadge 1.2s infinite;flex-shrink:0;}
.breaking-text{color:var(--text-secondary);font-size:11px;line-height:1.4;flex:1;}
.breaking-text strong{color:#ef4444;}


.share-btn.reddit{background:rgba(255,69,0,0.1);color:#ff4500;border:1px solid rgba(255,69,0,0.25);}
.share-btn.hn{background:rgba(255,102,0,0.1);color:#ff6600;border:1px solid rgba(255,102,0,0.25);}
.helpful-widget{display:flex;align-items:center;gap:10px;padding:14px 18px;background:var(--surface);border:1px solid var(--border);border-radius:8px;margin:20px 0;flex-wrap:wrap;}
.helpful-q{color:var(--text-secondary);font-size:12px;flex:1;min-width:160px;}
.helpful-btn{padding:7px 16px;border-radius:6px;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;border:1px solid var(--border);background:var(--card);color:var(--text-secondary);cursor:pointer;transition:0.2s;}
.helpful-btn:not(:disabled):hover,.helpful-btn.active{background:var(--accent);color:#000;border-color:var(--accent);}
.helpful-btn.no:not(:disabled):hover,.helpful-btn.no.active{background:var(--danger);color:#fff;border-color:var(--danger);}

.affiliate-strip{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:18px;margin-bottom:20px;}
.affiliate-strip-title{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--text-muted);margin-bottom:12px;}
.aff-item{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);text-decoration:none;transition:0.2s;}
.aff-item:last-child{border-bottom:none;padding-bottom:0;}
.aff-item:hover{opacity:0.85;}
.aff-item-icon{font-size:18px;flex-shrink:0;}
.aff-item-body{flex:1;}
.aff-item-name{color:#fff;font-size:12px;font-weight:600;line-height:1.2;}
.aff-item-desc{color:var(--text-muted);font-size:10px;line-height:1.3;margin-top:2px;}
.aff-item-badge{font-family:'JetBrains Mono',monospace;font-size:8px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:3px 7px;border-radius:3px;white-space:nowrap;}
.aff-badge-free{background:rgba(0,245,255,0.1);color:var(--accent);border:1px solid var(--accent-dim);}
.aff-badge-trial{background:rgba(139,92,246,0.1);color:#a78bfa;border:1px solid rgba(139,92,246,0.2);}
.rss-btn-feed{background:rgba(245,158,11,0.1);color:#f59e0b;border:1px solid rgba(245,158,11,0.2);}
.rss-btn-news{background:rgba(0,245,255,0.08);color:var(--accent);border:1px solid var(--accent-dim);}

