body.script:
//

/* Reading Progress */
(function(){
  var bar=document.getElementById('reading-progress');
  if(!bar)return;
  window.addEventListener('scroll',function(){
    var s=document.documentElement.scrollTop||document.body.scrollTop;
    var h=document.documentElement.scrollHeight-document.documentElement.clientHeight;
    bar.style.width=(h>0?Math.min(100,(s/h)*100):0)+'%';
  },{passive:true});
})();

/* Mobile Menu */
function toggleMobileMenu(btn){
  var m=document.getElementById('mobile-menu');
  if(!m)return;
  var open=m.classList.toggle('open');
  btn.classList.toggle('open',open);
  btn.setAttribute('aria-expanded',open);
}

/* Search Overlay */
function openSearch(){
  var o=document.getElementById('search-overlay');
  if(o){o.classList.add('open');setTimeout(function(){var i=document.getElementById('search-input');if(i)i.focus();},100);}
}
function closeSearch(){
  var o=document.getElementById('search-overlay');
  if(o)o.classList.remove('open');
}
document.addEventListener('keydown',function(e){
  if(e.key==='Escape')closeSearch();
  if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();openSearch();}
});
document.getElementById('search-overlay').addEventListener('click',function(e){if(e.target===this)closeSearch();});
document.getElementById('search-input').addEventListener('keydown',function(e){
  if(e.key==='Enter'){
    var q=this.value.trim();
    if(q)window.location.href='https://cyberbivash.blogspot.com/search?q='+encodeURIComponent(q);
  }
});

/* Timestamps */
(function(){
  var el=document.getElementById('intel-timestamp');
  if(el)el.textContent=new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC';
  var tu=document.getElementById('threat-update-time');
  if(tu)tu.textContent=new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC';
})();

/* Read Time */
(function(){
  var d=document.getElementById('read-time-display');
  if(!d)return;
  var body=document.querySelector('.post-body');
  if(!body)return;
  var words=(body.textContent||'').trim().split(/\s+/).length;
  var mins=Math.max(1,Math.round(words/200));
  d.textContent='⏱ '+mins+' min read';
})();

/* Auto TOC */
(function(){
  var toc=document.getElementById('auto-toc');
  var list=document.getElementById('toc-list');
  if(!toc||!list)return;
  var body=document.querySelector('.post-body');
  if(!body)return;
  var headings=body.querySelectorAll('h2,h3');
  if(headings.length<3)return;
  toc.classList.add('has-headings');
  var idx=0;
  headings.forEach(function(h){
    idx++;
    if(!h.id)h.id='toc-h-'+idx;
    var li=document.createElement('li');
    li.className=h.tagName==='H3'?'toc-h3':'';
    var a=document.createElement('a');
    a.href='#'+h.id;
    a.textContent=h.textContent;
    a.addEventListener('click',function(e){e.preventDefault();h.scrollIntoView({behavior:'smooth',block:'start'});});
    li.appendChild(a);
    list.appendChild(li);
  });
})();

/* Code Copy Buttons */
(function(){
  document.querySelectorAll('.post-body pre').forEach(function(pre){
    var btn=document.createElement('button');
    btn.className='copy-btn';
    btn.textContent='Copy';
    pre.style.position='relative';
    pre.appendChild(btn);
    btn.addEventListener('click',function(){
      var text=pre.querySelector('code')?pre.querySelector('code').textContent:pre.textContent;
      navigator.clipboard.writeText(text).then(function(){
        btn.textContent='Copied!';
        btn.classList.add('copied');
        setTimeout(function(){btn.textContent='Copy';btn.classList.remove('copied');},2000);
      }).catch(function(){btn.textContent='Error';});
    });
  });
})();

/* Share Buttons */
function shareTwitter(){
  var t=encodeURIComponent(document.title);
  var u=encodeURIComponent(window.location.href);
  window.open('https://twitter.com/intent/tweet?text='+t+'&url='+u+'&via=cyberdudebivash','_blank','width=600,height=400');
}
function shareLinkedIn(){
  var u=encodeURIComponent(window.location.href);
  window.open('https://www.linkedin.com/shareArticle?mini=true&url='+u,'_blank','width=600,height=500');
}
function copyLink(btn){
  navigator.clipboard.writeText(window.location.href).then(function(){
    btn.textContent='✓ Copied!';
    btn.classList.add('copied');
    setTimeout(function(){btn.textContent='🔗 Copy Link';btn.classList.remove('copied');},2000);
  });
}

/* FAQ Accordion */
function toggleFaq(item){
  var isOpen=item.classList.contains('open');
  document.querySelectorAll('.faq-item.open').forEach(function(i){i.classList.remove('open');});
  if(!isOpen)item.classList.add('open');
}

/* Sticky CTA Bar */
var scbClosed=false;
function closeStickyBar(){
  var bar=document.getElementById('sticky-cta');
  if(bar)bar.classList.add('hidden');
  scbClosed=true;
  try{sessionStorage.setItem('scb_closed','1');}catch(e){}
}
(function(){
  try{if(sessionStorage.getItem('scb_closed')){var b=document.getElementById('sticky-cta');if(b)b.classList.add('hidden');scbClosed=true;}}catch(e){}
  var shown=false;
  window.addEventListener('scroll',function(){
    if(scbClosed)return;
    var bar=document.getElementById('sticky-cta');
    if(!bar)return;
    if(window.scrollY>600&&!shown){shown=true;bar.classList.remove('hidden');}
    else if(window.scrollY<400&&shown){shown=false;bar.classList.add('hidden');}
  },{passive:true});
})();

/* Animated Counters */
(function(){
  var els=document.querySelectorAll('.counter-num[data-target]');
  if(!els.length||!('IntersectionObserver' in window))return;
  var obs=new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if(!e.isIntersecting)return;
      var el=e.target;
      var target=parseInt(el.getAttribute('data-target'));
      var start=0;var dur=1500;var startTime=null;
      function step(ts){
        if(!startTime)startTime=ts;
        var pct=Math.min((ts-startTime)/dur,1);
        var val=Math.floor(pct*pct*(3-2*pct)*target);
        el.textContent=val.toLocaleString()+'+';
        if(pct<1)requestAnimationFrame(step);
        else el.textContent=target.toLocaleString()+'+';
      }
      requestAnimationFrame(step);
      obs.unobserve(el);
    });
  },{threshold:0.5});
  els.forEach(function(el){obs.observe(el);});
})();

/* Lazy Load */
(function(){
  if('loading' in HTMLImageElement.prototype){
    document.querySelectorAll('img:not([loading])').forEach(function(img){img.setAttribute('loading','lazy');});
  }else if('IntersectionObserver' in window){
    var obs=new IntersectionObserver(function(entries){
      entries.forEach(function(e){if(e.isIntersecting){var img=e.target;if(img.dataset.src){img.src=img.dataset.src;}obs.unobserve(img);}});
    },{rootMargin:'200px'});
    document.querySelectorAll('img[data-src]').forEach(function(img){obs.observe(img);});
  }
})();

