/* ── Eco promo rotator ── */
function ecoSlide(id,idx){
  var card=document.getElementById(id);if(!card)return;
  card.querySelectorAll('.eco-promo-slide').forEach(function(s,i){s.classList.toggle('active',i===idx);});
  card.querySelectorAll('.eco-promo-dot').forEach(function(d,i){d.classList.toggle('active',i===idx);});
}
(function(){
  document.querySelectorAll('.eco-promo-card').forEach(function(card){
    if(!card.id)return;
    var n=card.querySelectorAll('.eco-promo-slide').length;
    if(n<2)return;
    var idx=0;
    setInterval(function(){idx=(idx+1)%n;ecoSlide(card.id,idx);},5000);
  });
})();

/* ── Canvas post banner generator ── */
(function(){
  var PALETTE={
    'threat intelligence':['#0a1628','#0d1e35','#00f5ff','#0066ff'],
    'vulnerabilities':['#1a0a0a','#200d0d','#ef4444','#dc2626'],
    'vulnerability':['#1a0a0a','#200d0d','#ef4444','#dc2626'],
    'zero-day':['#1a0000','#220000','#ff3333','#dc2626'],
    'zero-days':['#1a0000','#220000','#ff3333','#dc2626'],
    'cve':['#160a00','#1e0e00','#f97316','#ea580c'],
    'ransomware':['#1a1200','#221800','#f59e0b','#d97706'],
    'malware':['#180a00','#200d00','#fb923c','#f97316'],
    'ai security':['#0a0a1a','#0d0d22','#a78bfa','#8b5cf6'],
    'ai-security':['#0a0a1a','#0d0d22','#a78bfa','#8b5cf6'],
    'nation-state':['#0a1a10','#0d2215','#22c55e','#16a34a'],
    'apt':['#0a1a10','#0d2215','#22c55e','#16a34a'],
    'cloud security':['#0a0f1a','#0d1422','#60a5fa','#3b82f6'],
    'devsecops':['#0a1218','#0d1820','#06b6d4','#0891b2'],
    'incident response':['#1a0d00','#221200','#fb923c','#f97316'],
    'mitre':['#0a1010','#0d1818','#2dd4bf','#14b8a6'],
    'default':['#0d1420','#0a1628','#00f5ff','#0066ff']
  };

  function esc(s){return s?s.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#\d+;/g,function(m){try{return String.fromCharCode(parseInt(m.slice(2,-1)));}catch(e){return m;}}):''}
  function wrapText(ctx,text,maxW,x,y,lineH){
    var words=text.split(' ');var line='';var lines=[];
    for(var i=0;i<words.length;i++){
      var t=(line?line+' ':'')+words[i];
      if(ctx.measureText(t).width>maxW&&line){lines.push(line);line=words[i];}
      else{line=t;}
    }
    if(line)lines.push(line);
    lines=lines.slice(0,3);
    lines.forEach(function(l,i){ctx.fillText(l,x,y+i*lineH);});
    return lines.length;
  }

  function drawBanner(canvas,rawTitle,rawLabel){
    var dpr=window.devicePixelRatio||1;
    var W=canvas.width,H=canvas.height;
    var ctx=canvas.getContext('2d');
    var label=(rawLabel||'').toLowerCase();
    var pal=PALETTE[label]||PALETTE['default'];
    var bg1=pal[0],bg2=pal[1],acc=pal[2],acc2=pal[3];
    var title=esc(rawTitle||'Intelligence Report');

    /* Background gradient */
    var grd=ctx.createLinearGradient(0,0,W,H);
    grd.addColorStop(0,bg1);grd.addColorStop(1,bg2);
    ctx.fillStyle=grd;ctx.fillRect(0,0,W,H);

    /* Grid overlay */
    ctx.strokeStyle=acc;ctx.globalAlpha=0.05;ctx.lineWidth=1;
    for(var x=0;x<W;x+=53){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke();}
    for(var y=0;y<H;y+=52){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke();}
    ctx.globalAlpha=1;

    /* Glow orbs */
    var g1=ctx.createRadialGradient(W*0.75,H*0.25,0,W*0.75,H*0.25,W*0.4);
    g1.addColorStop(0,acc+'18');g1.addColorStop(1,'transparent');
    ctx.fillStyle=g1;ctx.fillRect(0,0,W,H);
    var g2=ctx.createRadialGradient(W*0.15,H*0.75,0,W*0.15,H*0.75,W*0.35);
    g2.addColorStop(0,acc2+'12');g2.addColorStop(1,'transparent');
    ctx.fillStyle=g2;ctx.fillRect(0,0,W,H);

    /* Top accent bar */
    var barGrd=ctx.createLinearGradient(0,0,W,0);
    barGrd.addColorStop(0,acc);barGrd.addColorStop(0.5,acc2);barGrd.addColorStop(1,'#8b5cf6');
    ctx.fillStyle=barGrd;ctx.fillRect(0,0,W,3);

    /* Brand text */
    ctx.fillStyle=acc;ctx.globalAlpha=0.75;
    ctx.font='bold 11px "JetBrains Mono",monospace';
    ctx.letterSpacing='2px';
    ctx.fillText('CYBERDUDEBIVASH® SENTINEL APEX',24,34);
    ctx.globalAlpha=1;

    /* Shield icon */
    ctx.save();
    ctx.translate(24,52);ctx.scale(1.4,1.4);
    ctx.strokeStyle=acc;ctx.lineWidth=2;ctx.globalAlpha=0.5;
    ctx.beginPath();
    ctx.moveTo(16,2);ctx.lineTo(2,8);ctx.lineTo(2,18);
    ctx.quadraticCurveTo(2,28,16,32);
    ctx.quadraticCurveTo(30,28,30,18);
    ctx.lineTo(30,8);ctx.closePath();ctx.stroke();
    ctx.restore();ctx.globalAlpha=1;

    /* Label badge */
    var displayLabel=(rawLabel||'INTEL REPORT').toUpperCase();
    ctx.font='bold 9px "JetBrains Mono",monospace';
    var lw=ctx.measureText(displayLabel).width;
    ctx.fillStyle=acc;ctx.globalAlpha=0.12;
    ctx.beginPath();ctx.roundRect(24,100,lw+24,22,3);ctx.fill();
    ctx.globalAlpha=0.6;
    ctx.strokeStyle=acc;ctx.lineWidth=0.8;
    ctx.beginPath();ctx.roundRect(24,100,lw+24,22,3);ctx.stroke();
    ctx.globalAlpha=1;
    ctx.fillStyle=acc;ctx.letterSpacing='1.5px';
    ctx.fillText(displayLabel,34,115);

    /* Title */
    ctx.fillStyle='#ffffff';
    ctx.font='800 15px "Outfit",Arial,sans-serif';
    ctx.letterSpacing='0px';
    wrapText(ctx,title,W-48,24,148,22);

    /* Bottom bar */
    ctx.fillStyle=bg1;ctx.globalAlpha=0.6;
    ctx.fillRect(0,H-30,W,30);ctx.globalAlpha=1;
    ctx.fillStyle=acc;ctx.globalAlpha=0.5;
    ctx.font='9px "JetBrains Mono",monospace';ctx.letterSpacing='1px';
    ctx.fillText('CYBERDUDEBIVASH.COM · THREAT INTELLIGENCE · AI SECURITY',24,H-10);
    ctx.globalAlpha=1;
  }

  function initBanners(){
    document.querySelectorAll('canvas.post-card-img-canvas').forEach(function(canvas){
      var title=canvas.getAttribute('data-post-title')||'';
      var label=canvas.getAttribute('data-post-label')||'';
      drawBanner(canvas,title,label);
    });
  }

  /* ── Urgency badges ── */
  function applyUrgencyBadges(){
    document.querySelectorAll('.post-card').forEach(function(card){
      var wrap=card.querySelector('.post-card-img-wrap');
      if(!wrap)return;
      var labels=Array.from(card.querySelectorAll('.post-card-label')).map(function(l){return l.textContent.toLowerCase().trim();});
      var title=(card.querySelector('.post-card-title')||{}).textContent||'';
      var tl=title.toLowerCase();
      var badge=document.createElement('span');
      badge.className='card-urgency-badge';
      if(labels.some(function(l){return l.includes('zero-day')||l.includes('zero day');})||tl.includes('zero-day')){
        badge.className+=' badge-zeroday';badge.textContent='ZERO-DAY';
      } else if(tl.includes('critical')||tl.includes('patch now')||tl.includes('actively exploit')){
        badge.className+=' badge-breaking';badge.textContent='BREAKING';
      } else if(labels.some(function(l){return l.includes('ransomware');})){
        badge.className+=' badge-hot';badge.textContent='HOT';
      } else if(labels.some(function(l){return l.includes('ai security')||l.includes('ai-security');})){
        badge.className+=' badge-new';badge.textContent='AI INTEL';
      } else {
        badge.className+=' badge-trending';badge.textContent='INTEL';
      }
      wrap.appendChild(badge);
    });
  }

  /* ── Label class enrichment ── */
  function enrichLabels(){
    document.querySelectorAll('.post-card-label').forEach(function(el){
      var t=el.textContent.toLowerCase().replace(/\s+/g,'-').replace(/[^a-z0-9-]/g,'');
      el.classList.add('l-'+t);
    });
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){initBanners();applyUrgencyBadges();enrichLabels();});
  } else {
    initBanners();applyUrgencyBadges();enrichLabels();
  }
})();
